# -*- coding: utf-8 -*-
"""Audit-driven UI translations (zh source -> English, Japanese).

Entries close the gaps reported by ``tools/i18n_audit.py`` and are merged into
the runtime catalog by :mod:`ui.localization`; existing hand-written entries
always take precedence.  Keys are the exact zh UI text.  Keys containing
placeholders (``{…}`` for an f-string slot, ``{name}``, ``{}``, ``%s``/``%d``)
become anchored templates: captured values are re-inserted verbatim (after the
normal UI translation pass), so paths, model names and counts are never
rewritten.  Every placeholder of a key must appear in its translations.

This module is data only and must not import Qt or other project modules.
"""
from __future__ import annotations

